func latestDeliveryUpdate(snapshot NoticeDeliverySnapshot) int64 {
	latest := snapshot.CapturedAt
	for _, delivery := range snapshot.Deliveries {
		updatedAt := delivery.UpdatedAt * int64(time.Millisecond)
		if updatedAt > latest {
			latest = updatedAt
		}
	}
	return latest
}

