	}
	issues = append(issues, SchemaValidationErrors(globalPath, global, false)...)

	projectPath := ""
	var project map[string]any
	var projectErr error
	if projectName != "" {
		projectPath = filepath.Join(home, "projects", projectName, "config.toml")
