	literal := strings.TrimSpace(text)
	if literal == "" {
		return nil, "", fmt.Errorf("value is required")
	}
	if spec.Type == TypeString || spec.Type == TypeDuration {
		if !strings.HasPrefix(literal, "\"") && !strings.HasPrefix(literal, "'") {
			literal = strconv.Quote(literal)
		}
	}
