55: func reviewComparison(ctx context.Context, db *store.DB) (map[string]any, error) {
56: 	projects, err := db.Projects(ctx)
57: 	if err != nil {
58: 		return nil, err
59: 	}
60: 	globalBuiltinLatency, err := builtinReviewLatency(ctx, db, 0)
61: 	if err != nil {
62: 		return nil, err
63: 	}
64: 	var rows []reviewComparisonRow
65: 	var totalRequests, totalVerdicts, totalWrong, totalInconclusive, totalMatched, totalPairs, projectsWithReviews int
66: 	var allLatency []int64
67: 	for _, project := range projects {
68: 		row, latencies, err := reviewComparisonForProject(ctx, db, project)
69: 		if err != nil {
70: 			return nil, err
71: 		}
72: 		if row.BuiltinMedianLatencyMS == nil && globalBuiltinLatency != nil {
73: 			row.BuiltinMedianLatencyMS = globalBuiltinLatency
74: 			limit := *globalBuiltinLatency * 3 / 2
75: 			row.LatencyLimitMS = &limit
76: 			if row.MedianLatencyMS != nil {
77: 				pass := *row.MedianLatencyMS <= limit
78: 				row.LatencyPass = &pass
79: 			}
80: 		}
81: 		rows = append(rows, row)
82: 		totalRequests += row.Requests
83: 		totalVerdicts += row.Verdicts
84: 		totalWrong += row.WrongHead
85: 		totalInconclusive += row.Inconclusive
86: 		totalMatched += row.RecallMatched
87: 		totalPairs += row.RecallPairs
88: 		allLatency = append(allLatency, latencies...)
89: 		if row.ReviewedHeads > 0 {
90: 			projectsWithReviews++
91: 		}
92: 	}
93: 	total := reviewComparisonRow{Project: "total", Requests: totalRequests, Verdicts: totalVerdicts, WrongHead: totalWrong, Inconclusive: totalInconclusive, RecallMatched: totalMatched, RecallPairs: totalPairs, Precision: "not measured in G1"}
94: 	for _, row := range rows {
95: 		total.ReviewedHeads += row.ReviewedHeads
96: 		total.UnmatchedPairs = append(total.UnmatchedPairs, row.UnmatchedPairs...)
97: 	}
98: 	total.ProjectsWithReviews = projectsWithReviews
99: 	samplePass := total.ReviewedHeads >= 50 && projectsWithReviews >= 2
100: 	total.SamplePass = &samplePass
101: 	if total.Requests > 0 {
102: 		total.Reliability = float64(total.Verdicts) / float64(total.Requests)
103: 		pass := total.Reliability >= 0.95
104: 		total.ReliabilityPass = &pass
105: 	}
106: 	if total.Requests > 0 {
107: 		total.WrongHeadRate = float64(total.WrongHead) / float64(total.Requests)
108: 	}
109: 	wrongPass := total.WrongHead == 0
110: 	total.WrongHeadPass = &wrongPass
111: 	if total.Verdicts > 0 {
112: 		total.InconclusiveShare = float64(total.Inconclusive) / float64(total.Verdicts)
113: 		pass := total.InconclusiveShare <= 0.10
114: 		total.InconclusivePass = &pass
115: 	}
116: 	if total.RecallPairs > 0 {
117: 		recall := float64(total.RecallMatched) / float64(total.RecallPairs)
118: 		total.Recall = &recall
119: 		pass := recall >= 0.90
120: 		total.RecallPass = &pass
121: 	}
122: 	if len(allLatency) > 0 {
123: 		median := medianInt64(allLatency)
124: 		total.MedianLatencyMS = &median
125: 	}
126: 	if globalBuiltinLatency != nil && total.MedianLatencyMS != nil {
127: 		median := *globalBuiltinLatency
128: 		total.BuiltinMedianLatencyMS = &median
129: 		limit := median * 3 / 2
130: 		total.LatencyLimitMS = &limit
131: 		pass := *total.MedianLatencyMS <= limit
132: 		total.LatencyPass = &pass
133: 	}
