60: func (db *DB) CreateGreenhouseFailureNoticeOnce(ctx context.Context, projectID, taskID int64, repository, head, reason string) (bool, error) {
61: 	data, err := json.Marshal(struct {
62: 		Repository string `json:"repo"`
