70: 		SELECT ?, ?, 'greenhouse_review_failed', ?, ?, ?
71: 		WHERE NOT EXISTS (SELECT 1 FROM notices WHERE task_id=? AND kind='greenhouse_review_failed' AND data_json=?)`,
72: 		projectID, taskID, summary, string(data), time.Now().UnixMilli(), taskID, string(data))
73: 	if err != nil {
74: 		return false, err
75: 	}
76: 	rows, err := result.RowsAffected()
77: 	if err != nil || rows == 0 {
78: 		return false, err
79: 	}
80: 	return true, db.PersistProject(ctx, projectID)
