+CREATE TRIGGER IF NOT EXISTS greenhouse_review_requests_no_delete BEFORE DELETE ON greenhouse_review_requests
+BEGIN SELECT RAISE(ABORT, 'Greenhouse review request is insert-only'); END;
+
